import{_ as a,o as e,c as i,a2 as r}from"./chunks/framework.Ky-Ipuyb.js";const h=JSON.parse('{"title":"ImGui API 가이드","description":"","frontmatter":{"lang":"ko","sourcePath":"docs/imgui/api.ko.md"},"headers":[],"relativePath":"ko/imgui/api.md","filePath":"ko/imgui/api.md"}'),l={name:"ko/imgui/api.md"};function o(d,t,n,s,c,m){return e(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="imgui-api-가이드" tabindex="-1">ImGui API 가이드 <a class="header-anchor" href="#imgui-api-가이드" aria-label="Permalink to &quot;ImGui API 가이드&quot;">​</a></h1><p>목적별 가이드로 사용법을 익힌 뒤 <a href="/ko/reference/imgui/" target="_self">API 레퍼런스</a>에서 인자와 반환값을 확인합니다. 목록의 요약으로 함수를 찾고 상세 페이지에서 사용 참고, 매개변수, 반환값, 네이티브 수명 제약을 읽습니다.</p><h2 id="올바른-진입점-찾기" tabindex="-1">올바른 진입점 찾기 <a class="header-anchor" href="#올바른-진입점-찾기" aria-label="Permalink to &quot;올바른 진입점 찾기&quot;">​</a></h2><table tabindex="0"><thead><tr><th>작업</th><th>진입점</th><th>가이드</th></tr></thead><tbody><tr><td>네이티브 창 연동</td><td>SFML.Init·ProcessEvent·Update·Render·Shutdown</td><td><a href="/ko/imgui/getting-started">시작</a></td></tr><tr><td>위젯 선언</td><td>ImGui.Button·Checkbox·SliderFloatEx</td><td><a href="/ko/imgui/widgets">상태</a></td></tr><tr><td>패널 구성</td><td>BeginChild·BeginTable·메뉴·팝업</td><td><a href="/ko/imgui/layout">레이아웃</a></td></tr><tr><td>UTF-8·콜백</td><td>InputTextEx·ListBoxCallbackEx·PlotLinesCallbackEx</td><td><a href="/ko/imgui/callbacks">입력</a></td></tr><tr><td>폰트·스타일</td><td>getFontAtlas·getStyleColors·SFML.GetStyle</td><td><a href="/ko/imgui/fonts">폰트</a></td></tr><tr><td>도형·창 전환</td><td>ImGui.GetWindowDrawList·SFML.SetCurrentWindow</td><td><a href="/ko/imgui/rendering">렌더링</a></td></tr></tbody></table><h2 id="javascript-계약으로-읽기" tabindex="-1">JavaScript 계약으로 읽기 <a class="header-anchor" href="#javascript-계약으로-읽기" aria-label="Permalink to &quot;JavaScript 계약으로 읽기&quot;">​</a></h2><p><a href="/ko/reference/imgui/functions/ImGui.SliderFloatEx.html" target="_self">SliderFloatEx</a>는 쓰기 가능한 Float32Array, 두 경계, 서식 문자열, 플래그를 받습니다. boolean은 편집 여부이고 현재 값은 배열에 있습니다. 네이티브 매개변수 이름이 JavaScript 숫자를 쓰기 가능한 값으로 만들지는 않습니다.</p><p>Button은 기본 크기, ButtonEx는 크기 지정입니다. PushStyleVar는 스칼라, PushStyleVarVec2는 벡터입니다. Ex가 항상 콜백을 뜻하지 않으므로 구체적인 시그니처를 확인합니다.</p><p>ImVec2Like는 <code>[ x, y ]</code>나 <code>{ x, y }</code> 같은 벡터 값을 받습니다. 수정할 숫자 포인터는 함수가 명시한 타입 배열이 필요합니다. ImGuiInputTextCallbackData 같은 구조체 핸들은 바인딩이 반환하는 타입 표식이 있는 불투명 객체입니다. 텍스처 ID와 원시 포인터 인자는 bigint이며 구조체 핸들과 바꿔 쓸 수 없습니다. 추측한 주소로 만들지 마세요.</p><p>ImGui.GetIO/GetStyle은 네이티브 핸들, SFML.GetIO/GetStyle은 현재 창의 편의 쓰기 뷰입니다. 핸들을 요구하는 도우미에 뷰를 넘길 수 없습니다.</p><h2 id="호출-전-확인" tabindex="-1">호출 전 확인 <a class="header-anchor" href="#호출-전-확인" aria-label="Permalink to &quot;호출 전 확인&quot;">​</a></h2><ol><li>초기화된 컨텍스트·활성 프레임·보이는 부모가 필요한가.</li><li>인자가 복사·직접 수정·대여 중 어떤 방식인가.</li><li>null이 창 닫기 버튼 같은 기능을 끄는가.</li><li>boolean은 활성화·내용 변경·선택·가시성 중 무엇인가.</li><li>필요한 End/Pop과 호출 조건은 무엇인가.</li><li>반환된 핸들·뷰는 언제까지 유효한가.</li></ol><p>TypeScript 도구와 구현 확인에는 <a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/index.ts" target="_blank" rel="noreferrer">패키지 export</a>, <a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/sfml.ts" target="_blank" rel="noreferrer">SFML 연동</a>, <a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/imgui/index.ts" target="_blank" rel="noreferrer">ImGui 모듈</a>을 참고합니다.</p><p>설명은 선언 옆에서 영어·중국어·일본어·한국어 요약과 상세로 관리하며 TypeDoc이 직접 읽습니다. 문제를 보고할 때 함수, 언어, 예상 JavaScript 호출, 실제 결과를 포함하세요.</p>',13)])])}const p=a(l,[["render",o]]);export{h as __pageData,p as default};
